INSERT INTO public.triage_results (id, alert_id, verdict, recommended_severity, confidence, risk_score, summary, reasoning, recommended_actions, mitre_techniques, should_escalate, false_positive_reason, engine, model_name, prompt_version, latency_ms, tokens_used, raw_response, created_at) VALUES ('054af6ac-5c73-4ca6-8ce8-c8decbc092d9', '0adfd72c-8636-4025-9fdd-220f99a796aa', 'true_positive', 'high', 0.88, 82, 'Ataque de fuerza bruta SSH contra srv-web01 desde 203.0.113.45. Se observan 48 fallos en 3 minutos y un intento exitoso posterior. Riesgo alto de acceso no autorizado.', 'Regla 5710 de nivel 10 sobre srv-web01; activo con criticidad high. Se correlacionan 4 señales y reputación de 203.0.113.45.', '[{"type": "validation", "owner": "SOC L1", "action": "Validar la actividad con logs de EDR, firewall y autenticación.", "priority": 1, "sla_minutes": 30}, {"type": "containment", "owner": "SOC L2", "action": "Bloquear el origen y recolectar evidencia.", "priority": 2, "sla_minutes": 45}, {"type": "escalation", "owner": "SOC Lead", "action": "Escalar a incidente si se confirma.", "priority": 3, "sla_minutes": 60}]', '["T1110", "T1078"]', true, NULL, 'langchain', 'llama3.1:8b', 'triage-v1', 1790, 648, '{"seed": true, "cycle": 0}', '2026-09-30 16:33:00-05');
INSERT INTO public.triage_results (id, alert_id, verdict, recommended_severity, confidence, risk_score, summary, reasoning, recommended_actions, mitre_techniques, should_escalate, false_positive_reason, engine, model_name, prompt_version, latency_ms, tokens_used, raw_response, created_at) VALUES ('6e610876-1f54-473d-a7b3-68978b96bc93', '24bda392-bc2f-425f-872b-79a6c8ebbf93', 'true_positive', 'critical', 0.75, 96, 'Actividad compatible con ransomware en srv-db01: 1,842 archivos cifrados y un binario no firmado ejecutándose con la cuenta de respaldo. Requiere contención inmediata y activación del plan de crisis.', 'Regla 100210 de nivel 15 sobre srv-db01; activo con criticidad critical. Se correlacionan 4 señales y reputación de 10.10.1.20.', '[{"type": "containment", "owner": "SOC L2", "action": "Aislar el activo y preservar evidencia volátil.", "priority": 1, "sla_minutes": 15}, {"type": "containment", "owner": "Infraestructura", "action": "Bloquear indicadores en firewall, proxy y DNS.", "priority": 2, "sla_minutes": 20}, {"type": "escalation", "owner": "SOC Lead", "action": "Abrir incidente y activar el plan de respuesta.", "priority": 3, "sla_minutes": 30}]', '["T1486", "T1204"]', true, NULL, 'langchain', 'llama3.1:8b', 'triage-v1', 1753, 880, '{"seed": true, "cycle": 0}', '2026-10-01 14:46:00-05');
INSERT INTO public.triage_results (id, alert_id, verdict, recommended_severity, confidence, risk_score, summary, reasoning, recommended_actions, mitre_techniques, should_escalate, false_positive_reason, engine, model_name, prompt_version, latency_ms, tokens_used, raw_response, created_at) VALUES ('9f2629ad-20df-4f48-8db5-6433d771725c', '5c939303-f3c4-423e-a3de-70fd5fbc899d', 'true_positive', 'critical', 0.88, 91, 'Beaconing periódico hacia un dominio de C2 desde un pod de producción. La combinación de PowerShell ofuscado y tráfico TLS periódico sugiere un implante activo.', 'Regla 100305 de nivel 13 sobre k8s-prod-01; activo con criticidad high. Se correlacionan 4 señales y reputación de 10.10.4.10.', '[{"type": "containment", "owner": "SOC L2", "action": "Aislar el activo y preservar evidencia volátil.", "priority": 1, "sla_minutes": 15}, {"type": "containment", "owner": "Infraestructura", "action": "Bloquear indicadores en firewall, proxy y DNS.", "priority": 2, "sla_minutes": 20}, {"type": "escalation", "owner": "SOC Lead", "action": "Abrir incidente y activar el plan de respuesta.", "priority": 3, "sla_minutes": 30}]', '["T1071", "T1059"]', true, NULL, 'heuristic-local', 'soc-lite-rules-v1', 'triage-v1', 2672, 0, '{"seed": true, "cycle": 0}', '2026-10-02 17:00:00-05');
